css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .escena-wrap{display: grid; grid-template-columns: 1fr auto; gap: 14px; align-items: center;}
.mz .escena-svg{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px; background: #fff;}
.mz .escena-svg svg{width: 100%; height: 210px; display: block;}
.mz .escena-tabla{display: flex; flex-direction: column; gap: 7px;}
.mz .escena-fila{display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 700;}
.mz .escena-fila svg{width: 28px; height: 28px; flex-shrink: 0;}
.mz .escena-hueco{width: 36px; height: 24px; border: 1.5px solid var(--bosque); border-radius: 5px; flex-shrink: 0;}
.mz .nombrar-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;}
.mz .nombrar-caja{display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .nombrar-svg{width: 100%; min-height: 56px; display: flex; align-items: center; justify-content: center;}
.mz .nombrar-svg svg{width: 52px; height: 52px;}
.mz .nombrar-linea{width: 100%; border-bottom: 1.5px solid var(--bosque); height: 22px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 7px;}
.mz .vf-fila{display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center; font-size: 13px;}
.mz .vf-frase{line-height: 1.4;}
.mz .vf-opcion{display: flex; align-items: center; gap: 4px; font-weight: 700;}
.mz .vf-circ{width: 22px; height: 22px; border: 1.5px solid var(--bosque); border-radius: 50%;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 11.5px; font-weight: 700; text-align: center; line-height: 1.2; min-height: 30px; display: flex; align-items: center; justify-content: center;}
.mz .dibujar-hueco{width: 100%; height: 90px; border: 1.5px solid var(--bosque); border-radius: 8px;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .txt-flex{line-height: 1.875 !important;}
